     * List Session Logs.
     *
     * List interaction logs for a session.
     *
     * Returns all bot-user interactions for debugging and analysis.
     *
     * Scopes: automation:read.
     *
     * @param  ?int  $skip  Pagination offset
     * @param  ?int  $limit  Pagination limit
     * @return list<BotInteractionLog>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Automation/list_session_logs_api_v1_automation_sessions__session_id__logs_get
     */
    public function listSessionLogs(string $sessionId, ?int $skip = null, ?int $limit = null): array
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/sessions/'.Payload::segment($sessionId).'/logs',
            query: Payload::query(['skip' => $skip, 'limit' => $limit]),
        ));

        return Hydrate::list($response->data(), BotInteractionLog::fromArray(...));
    }

    /**
     * Get Bot Templates.
     *
     * Get available bot templates.
     *
     * Two response shapes:
     *
     * * No language param (legacy) — returns one template per bot_type (Support, Sales, FAQ, …).
     * Used by older UI flows. * With language param (Phase 2) — returns the unified assistant preset
     * gallery: 5 presets (support / sales / faq / email / custom), each with a localised
     * personality_prompt + greeting and bot_type='assistant'. Used by the new bot creator (Step 2).
     *
     * Scopes: automation:read.
     *
     * @param  ?string  $language  Optional ISO-639-1 language code (e.g. 'en', 'de'). When provided, returns the Phase-2 assistant preset gallery filtered by language. When omitted, returns the legacy per-bot-type template list.
     * @return array<array-key, mixed>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Automation/get_bot_templates_api_v1_automation_templates_get
     */
    public function getBotTemplates(?string $language = null): array
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/templates',
            query: Payload::query(['language' => $language]),
        ));

        return $response->data();
    }

    /**
     * Get Bot Template.
     *
     * Get a specific bot template by type.
     *
     * Args: bot_type: One of 'support', 'sales', 'custom'
     *
     * Scopes: automation:read.
     *
     * @return array<array-key, mixed>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Automation/get_bot_template_api_v1_automation_templates__bot_type__get
     */
    public function getBotTemplate(string $botType): array
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/templates/'.Payload::segment($botType),
        ));

        return $response->data();
    }
}
